package com.german_software_engineers.trainerapp;

import android.os.Bundle;
import android.support.design.widget.FloatingActionButton;
import android.support.design.widget.Snackbar;
import android.support.v7.app.AppCompatActivity;
import android.support.v7.widget.Toolbar;
import android.view.View;
import android.widget.TextView;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;

public class InfoActivity extends AppCompatActivity {

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_info);
        Toolbar toolbar = (Toolbar) findViewById(R.id.toolbar);
        setSupportActionBar(toolbar);

        FloatingActionButton fab = (FloatingActionButton) findViewById(R.id.fab);
        fab.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View view) {
                Snackbar.make(view, "Contact us on GitHub", Snackbar.LENGTH_LONG)
                        .setAction("Action", null).show();
            }
        });
        getSupportActionBar().setDisplayHomeAsUpEnabled(true);

        showLicense();
    }

    /**
     * Shows the complete license on the info page. The license document is too big to be
     * stored in a single string resource, therefore it is kept as a raw resource and read
     * in here. If it cannot be read, the short fallback text stays visible.
     */
    private void showLicense() {
        TextView licenseTextView = (TextView) findViewById(R.id.licenseTextView);
        if (licenseTextView == null) {
            return;
        }

        String license = readLicense();
        if (license != null) {
            licenseTextView.setText(getString(R.string.license_title) + "\n\n" + license);
        }
    }

    /**
     * @return the complete license text or {@code null} if it could not be read.
     */
    private String readLicense() {
        InputStream inputStream = null;
        BufferedReader reader = null;
        try {
            inputStream = getResources().openRawResource(R.raw.license_gpl_v3);
            reader = new BufferedReader(new InputStreamReader(inputStream, "UTF-8"));
            StringBuilder licenseBuilder = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                licenseBuilder.append(line).append('\n');
            }
            return licenseBuilder.toString();
        } catch (IOException exception) {
            return null;
        } finally {
            closeQuietly(reader);
            closeQuietly(inputStream);
        }
    }

    private void closeQuietly(java.io.Closeable closeable) {
        if (closeable != null) {
            try {
                closeable.close();
            } catch (IOException ignored) {
                // Nothing we can do here.
            }
        }
    }
}

